package main

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"runtime"
)

type trackingFile struct {
	*os.File
}

func (t *trackingFile) Read(p []byte) (int, error) { return t.File.Read(p) }
func (t *trackingFile) Seek(o int64, w int) (int64, error) { return t.File.Seek(o, w) }
func (t *trackingFile) Close() error {
	buf := make([]byte, 4096)
	n := runtime.Stack(buf, false)
	fmt.Printf("CLOSE called from:\n%s\n", buf[:n])
	return t.File.Close()
}

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		io.Copy(io.Discard, r.Body)
		w.WriteHeader(429)
	}))
	defer srv.Close()

	f, _ := os.CreateTemp("", "probe-*")
	f.WriteString("hello")
	f.Seek(0, io.SeekStart)
	tf := &trackingFile{f}

	req, _ := http.NewRequest(http.MethodPost, srv.URL, tf)
	req.GetBody = func() (io.ReadCloser, error) {
		fmt.Println("GetBody called")
		tf.Seek(0, io.SeekStart)
		return io.NopCloser(tf), nil
	}
	req.ContentLength = 5

	resp, err := srv.Client().Do(req)
	fmt.Println("err:", err, "resp:", resp.StatusCode)
}
